#!/usr/bin/env bash
# Generated by scripts/build-deploy.sh — do not edit directly.
# setup-pandoc.sh — Installs/updates Pandoc
# Safe to re-run — detects existing install and upgrades or migrates as needed.
#
# macOS: Uses Homebrew (brew install pandoc).
#        If pandoc was previously installed via a non-preferred method, migrates to Homebrew.
# Linux: Uses apt install pandoc (Debian/Ubuntu). Skips with warning on other distros.
#
# See reference/tool-registry.md for install source details.

set -euo pipefail

# --- Shared library ---
# aitools-lib.sh -- shared helpers for all aitools bash scripts
# Sourced, not executed directly. No shebang, no set -euo pipefail (caller sets it).
#
# Provides: platform detection, display_path, read_config_key, logging_init,
# log/log_ok/log_error/log_warn, write_summary, show_summary.
#
# Usage:
#   source "$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)/aitools-lib.sh"
#   logging_init "script-name"
#
# Entry points (aitools, aitools-install) override log functions after sourcing
# for specialized logging (file-only, JSONL, etc.).

# ---------------------------------------------------------------------------
# Platform detection
# ---------------------------------------------------------------------------
IS_MACOS=false
IS_WINDOWS=false
case "$(uname -s)" in
    Darwin*)              IS_MACOS=true ;;
    MINGW*|MSYS*|CYGWIN*) IS_WINDOWS=true ;;
esac

# ---------------------------------------------------------------------------
# Log directory (platform-aware)
# ---------------------------------------------------------------------------
AITOOLS_LOG_DIR="${XDG_STATE_HOME:-$HOME/.local/state}/aitools"
$IS_MACOS && AITOOLS_LOG_DIR="$HOME/Library/Logs/aitools"

# ---------------------------------------------------------------------------
# Module-level counters (safe for sourcing without logging_init under set -u)
# ---------------------------------------------------------------------------
ERRORS=0
WARNINGS=0

# ---------------------------------------------------------------------------
# Display-friendly path (native Windows on MSYS, no-op elsewhere)
# ---------------------------------------------------------------------------
display_path() {
    if command -v cygpath &>/dev/null; then
        cygpath -w "$1"
    else
        printf '%s' "$1"
    fi
}

# ---------------------------------------------------------------------------
# Config reader (pure bash, handles UTF-8 BOM)
# ---------------------------------------------------------------------------
# Read a top-level string value from a JSON config file.
# Handles UTF-8 BOM (PowerShell 5.x writes one) and JSON-escaped backslashes.
read_config_key() {
    local file="$1" key="$2"
    [ -f "$file" ] || return 1
    local val
    val=$(tr -d '\357\273\277' < "$file" \
        | grep -o "\"$key\"[[:space:]]*:[[:space:]]*\"[^\"]*\"" \
        | head -1 \
        | cut -d'"' -f4)
    [ -n "$val" ] || return 1
    # Unescape JSON backslashes: \\ -> \
    printf '%b' "$val"
}

# ---------------------------------------------------------------------------
# Logging init
# ---------------------------------------------------------------------------
# Sets SCRIPT_NAME, LOG_DIR, LOG_FILE; resets ERRORS, WARNINGS; creates log dir.
# Usage: logging_init "setup-foo"
logging_init() {
    SCRIPT_NAME="${1:?logging_init requires a script name}"
    LOG_DIR="$AITOOLS_LOG_DIR"
    LOG_FILE="$LOG_DIR/deploy.log"
    mkdir -p "$LOG_DIR"
    ERRORS=0
    WARNINGS=0
}

# ---------------------------------------------------------------------------
# Standard logging (Pattern A: console + log file, with [level] tag)
# ---------------------------------------------------------------------------
log() {
    local level="${2:-info}"
    local ts; ts="$(date -u +%Y-%m-%dT%H:%M:%SZ)"
    local line="[$ts] [$SCRIPT_NAME] [$level] $1"
    printf '%s\n' "$line" >> "$LOG_FILE"
    case "$level" in
        error) printf '\033[31m%s\033[0m\n' "$line" ;;
        warn)  printf '\033[33m%s\033[0m\n' "$line" ;;
        *)     printf '%s\n' "$line" ;;
    esac
}
log_ok()    { log "$1" "ok"; }
log_error() { log "$1" "error"; ERRORS=$((ERRORS + 1)); }
log_warn()  { log "$1" "warn"; WARNINGS=$((WARNINGS + 1)); }

# ---------------------------------------------------------------------------
# Summary writer (3-arg: category, tool, detail)
# ---------------------------------------------------------------------------
write_summary() {
    if [ -n "${AITOOLS_SUMMARY_FILE:-}" ]; then
        printf '%s|%s|%s\n' "$1" "$2" "$3" >> "$AITOOLS_SUMMARY_FILE"
    fi
}

# ---------------------------------------------------------------------------
# Summary panel renderer
# ---------------------------------------------------------------------------
# Reads AITOOLS_SUMMARY_FILE, displays colored panel, cleans up.
# Silent no-op if file unset, missing, or empty.
show_summary() {
    local sfile="${AITOOLS_SUMMARY_FILE:-}"
    [ -n "$sfile" ] || return 0
    [ -f "$sfile" ] || return 0
    [ -s "$sfile" ] || { rm -f "$sfile"; return 0; }

    # Dedup by tool name: highest severity wins (ERROR > WARN > OK).
    # ACTIONs (empty tool name) are never deduped. DETAIL lines collected separately.
    # Output is pre-sorted: OK+details, WARN+details, ERROR+details, ACTIONs.
    local deduped
    deduped=$(perl -F'\|' -lane '
        BEGIN { %rank = (OK => 1, WARN => 2, ERROR => 3); }
        $cat = $F[0]; $tool = $F[1]; $det = join("|", @F[2..$#F]);
        if ($cat eq "DETAIL") {
            push @{$details{$tool}}, $det; next;
        }
        if ($cat eq "ACTION" || $tool eq "") {
            push @actions, $_; next;
        }
        $r = $rank{$cat} // 0;
        if (!exists $best{$tool}) {
            push @order, $tool;
            $best{$tool} = $cat; $detail{$tool} = $det;
        } elsif ($r > ($rank{$best{$tool}} // 0)) {
            $best{$tool} = $cat; $detail{$tool} = $det;
        }
        END {
            my (@ok, @warn, @err);
            for my $t (@order) {
                my @g = ("$best{$t}|$t|$detail{$t}",
                         map { "DETAIL|$t|$_" } @{$details{$t} // []});
                if    ($best{$t} eq "OK")    { push @ok,   @g }
                elsif ($best{$t} eq "WARN")  { push @warn, @g }
                elsif ($best{$t} eq "ERROR") { push @err,  @g }
            }
            print for @ok, @warn, @err, @actions;
        }
    ' "$sfile")

    # Single-pass display: Perl output is pre-sorted by severity.
    # DETAIL lines inherit the color of their preceding parent entry.
    echo ""
    echo "────────────────────────────────────────────────────────"
    local last_color="" first_action=true
    while IFS='|' read -r cat tool detail; do
        case "$cat" in
            OK)
                last_color='\033[32m'
                printf '\033[32m  [ok]  %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            WARN)
                last_color='\033[33m'
                printf '\033[33m  [!]   %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            ERROR)
                last_color='\033[31m'
                printf '\033[31m  [ERR] %-16s %s\033[0m\n' "$tool" "$detail"
                ;;
            DETAIL)
                printf '%b                          %s\033[0m\n' "$last_color" "$detail"
                ;;
            ACTION)
                if [ "$first_action" = true ]; then
                    echo ""
                    printf '\033[1;35m  ACTION REQUIRED -- run before tools are ready:\033[0m\n'
                    first_action=false
                fi
                printf '\033[1;35m  >>  %s\033[0m\n' "$detail"
                ;;
        esac
    done <<< "$deduped"
    echo "────────────────────────────────────────────────────────"

    # Preserve summary for log compliance checks
    if [ "${AITOOLS_PRESERVE_SUMMARY:-}" = "1" ]; then
        # cp may fail if log dir was cleaned up; non-blocking (summary already displayed)
        if ! cp "$sfile" "$LOG_DIR/last-summary.txt" 2>/dev/null; then
            printf 'warning: could not preserve summary file\n' >&2
        fi
    fi
    # Cleanup summary file (already displayed; rm -f ignores nonexistent files)
    rm -f "$sfile"
}
logging_init "setup-pandoc"

# --- OS guard ---
case "$(uname -s)" in
    MINGW*|MSYS*|CYGWIN*)
        log_error "This script is for macOS/Linux. On Windows, use ${SCRIPT_NAME}.ps1 instead."
        exit 1 ;;
esac

OS_NAME="$(uname -s)"

# --- Install/update ---
case "$OS_NAME" in
    Darwin)
        # macOS: Homebrew is the preferred method
        if ! command -v brew &>/dev/null; then
            log_error "Homebrew not found. Install pandoc manually:"
            log_error "  1. Install Homebrew: https://brew.sh"
            log_error "  2. brew install pandoc"
            exit 1
        fi

        if command -v pandoc &>/dev/null; then
            pandoc_path="$(command -v pandoc)"
            pandoc_version="$(pandoc --version | head -1)"
            log "Pandoc $pandoc_version found at $pandoc_path"

            # Check if installed via Homebrew (path contains /opt/homebrew/ or /usr/local/)
            if [[ "$pandoc_path" == /opt/homebrew/* ]] || [[ "$pandoc_path" == /usr/local/* ]]; then
                log "Already installed via Homebrew — upgrading..."
                UPGRADE_OUTPUT=$(brew upgrade pandoc 2>&1) || true
                if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'already installed\|up.to.date\|No available upgrade'; then
                    log_ok "Pandoc already up to date"
                    write_summary OK "pandoc" "$(pandoc --version | head -1)"
                else
                    printf '%s\n' "$UPGRADE_OUTPUT" | while IFS= read -r line; do log "$line"; done
                    if printf '%s\n' "$UPGRADE_OUTPUT" | grep -qi 'error\|fatal'; then
                        log_error "brew upgrade pandoc failed (see log above)"
                        write_summary ERROR "pandoc" "brew upgrade failed"
                    else
                        log_ok "Pandoc $(pandoc --version | head -1)"
                        write_summary OK "pandoc" "$(pandoc --version | head -1)"
                    fi
                fi
            else
                # Not Homebrew — migrate
                log_warn "Pandoc installed via non-preferred method at $pandoc_path"
                log "Migrating to Homebrew..."

                # Detect and clean up known non-preferred installs
                if command -v conda &>/dev/null && conda list pandoc 2>/dev/null | grep -q pandoc; then
                    log_warn "Removing conda pandoc..."
                    # Cleanup: conda remove may fail if partially removed; non-blocking
                    conda remove -y pandoc 2>/dev/null || true
                fi
                if command -v port &>/dev/null && port installed pandoc 2>/dev/null | grep -q pandoc; then
                    log_warn "Removing MacPorts pandoc..."
                    # Cleanup: port uninstall may fail if partially removed; non-blocking
                    sudo port uninstall pandoc 2>/dev/null || true
                fi
                if [ -f "$HOME/.cabal/bin/pandoc" ]; then
                    log_warn "Removing Cabal pandoc..."
                    # Cleanup: cabal binary may already be gone; non-blocking
                    rm -f "$HOME/.cabal/bin/pandoc" 2>/dev/null || true
                fi

                if ! brew install pandoc 2>&1 | while IFS= read -r line; do log "$line"; done; then
                    log_error "brew install pandoc failed"
                    write_summary ERROR "pandoc" "brew install failed"
                fi

                if command -v pandoc &>/dev/null; then
                    log_ok "Migrated to Homebrew: Pandoc $(pandoc --version | head -1)"
                    log_ok "Install path: $(command -v pandoc)"
                    write_summary OK "pandoc" "$(pandoc --version | head -1)"
                else
                    log_error "Homebrew install succeeded but 'pandoc' not found in PATH"
                    write_summary ERROR "pandoc" "installed but not on PATH"
                fi
            fi
        else
            # Fresh install
            log "Installing Pandoc via Homebrew..."
            if ! brew install pandoc 2>&1 | while IFS= read -r line; do log "$line"; done; then
                log_error "brew install pandoc failed"
                write_summary ERROR "pandoc" "brew install failed"
            fi

            if command -v pandoc &>/dev/null; then
                log_ok "Pandoc installed ($(pandoc --version | head -1))"
                log_ok "Install path: $(command -v pandoc)"
                write_summary OK "pandoc" "$(pandoc --version | head -1)"
            else
                log_error "brew install completed but 'pandoc' not found in PATH"
                write_summary ERROR "pandoc" "installed but not on PATH"
            fi
        fi
        ;;

    *)
        # Linux: apt is the preferred method
        if command -v apt-get &>/dev/null; then
            if command -v pandoc &>/dev/null; then
                log_ok "Pandoc already installed ($(pandoc --version | head -1))"
                write_summary OK "pandoc" "$(pandoc --version | head -1)"
            else
                log "Installing Pandoc via apt..."
                if ! { sudo apt-get update -qq && sudo apt-get install -y pandoc; } 2>&1 | while IFS= read -r line; do log "$line"; done; then
                    log_error "apt-get install pandoc failed"
                    write_summary ERROR "pandoc" "apt-get install failed"
                fi
                if command -v pandoc &>/dev/null; then
                    log_ok "Pandoc installed ($(pandoc --version | head -1))"
                    write_summary OK "pandoc" "$(pandoc --version | head -1)"
                else
                    log_error "apt install completed but 'pandoc' not found in PATH"
                    write_summary ERROR "pandoc" "installed but not on PATH"
                fi
            fi
        else
            log_error "No supported package manager found (apt). Install pandoc manually: https://pandoc.org/installing.html"
            write_summary ERROR "pandoc" "no supported package manager"
        fi
        ;;
esac

# --- Exit ---
if [ "$ERRORS" -gt 0 ]; then
    log "FAILED with $ERRORS error(s)" "error"
    exit 1
elif [ "$WARNINGS" -gt 0 ]; then
    log "COMPLETED with $WARNINGS warning(s)" "warn"
    exit 0
else
    log "COMPLETED successfully" "ok"
    exit 0
fi
